var ORIGIN = "https://8828.5udk.com";
var API = ORIGIN + "/douyin/douyin622web.ashx";
var LIBBASE = "https://cdn.jsdelivr.net/gh/ericxiaox/reader-backup@main/libs/";




function loadScript(src, cb){
  var s=document.createElement('script'); s.src=src;
  s.onload=function(){ if(cb) cb(); };
  s.onerror=function(){ if(bar) bar.textContent='库加载失败: '+src; };
  document.head.appendChild(s);
}

var cur = 0, total = 0, page = 1, pagecount = 999, slides = [], loading = false;

var pwrap=document.getElementById('pwrap'), pbar=document.getElementById('pbar');
var ctlTimer=null;
function setCtl(v){ if(pwrap){ pwrap.style.opacity = v?'1':'0'; } }
function showCtl(keep){ setCtl(1); if(ctlTimer){ clearTimeout(ctlTimer); ctlTimer=null; } if(!keep){ ctlTimer=setTimeout(function(){ setCtl(0); },3000); } }
function ptXY(e){
  try{
    var t=null;
    if(e.touches&&e.touches.length){ t=e.touches[0]; }
    else if(e.changedTouches&&e.changedTouches.length){ t=e.changedTouches[0]; }
    if(t&&typeof t.clientX==='number'){ return {x:t.clientX,y:t.clientY}; }
    if(typeof e.clientX==='number'){ return {x:e.clientX,y:e.clientY}; }
  }catch(_){}
  return {x:0,y:sy};
}
function updateProgress(){
  var v=(slides[cur]&&slides[cur].vid)?slides[cur].vid:null;
  if(!v||!isFinite(v.duration)||v.duration<=0){ if(pbar){ pbar.style.width='0%'; } return; }
  if(pbar){ pbar.style.width=((v.currentTime/v.duration)*100).toFixed(2)+'%'; }
