  s.onerror=function(){ var s2=document.createElement('script'); s2.src='https://cdn.jsdelivr.net/gh/ericxiaox/reader-backup@main/libs/hls.min_v1.js'; s2.onload=function(){ loadPage(1); }; s2.onerror=function(){ bar.textContent='播放库加载失败'; }; document.head.appendChild(s2); };
  document.head.appendChild(s);
