   导读页与搜索结果每行都带 forum-{fid}-1.html -> 按此过滤；
   版块页行内无 fid（实测集合为空）-> 一律保留，不会误杀。
   注意：色花文学整区（154/135/137/138/136/139）**永久排除**（CSAM 铁律），
   不在本白名单内 -> 首页/搜索里出现的文学区帖子会被自动过滤掉。 */
var FIDS = { '95': 1, '166': 1, '141': 1, '142': 1,
             '155': 1, '125': 1, '50': 1, '48': 1, '49': 1, '117': 1, '165': 1,
             '2': 1, '36': 1, '37': 1, '103': 1, '107': 1, '160': 1,
             '104': 1, '38': 1, '151': 1, '152': 1, '39': 1 };

/* ① 站务类 typeid —— 站方自己给帖子打的结构化分类，**精确排除、零误杀**。
