while (pc.indexOf('<!--') !== -1) {
  var _ci = pc.indexOf('<!--');
  var _ce = pc.indexOf('-->', _ci + 4);
  if (_ce === -1) { pc = pc.slice(0, _ci); break; }
  pc = pc.slice(0, _ci) + pc.slice(_ce + 3);
}
