var OUT=[];
var h=String(result==null?"":result);
var parts=h.split("<article");
for(var i=1;i<parts.length;i++){
  var a=parts[i];
  var lm=a.match(/href="(?:https?:\/\/[^"\/]+)?(\/archives\/\d+\/)"/);
  if(!lm)continue;
  var tm=a.match(/<h2[^>]*>([\s\S]*?)<\/h2>/);
  var t=tm?tm[1].replace(/<[^>]*>/g,"").replace(/\s+/g," ").replace(/\s*热搜\s*HOT\s*$/,"").trim():"";
  if(!t){var idm=lm[1].match(/\d+/);t="文章 "+idm[0];}
  var im=a.match(/loadBannerDirect\('([^']+)'/);
  var dm=a.match(/itemprop="datePublished"[^>]*content="([^"]+)"/);
  var dt=dm?dm[1].slice(0,10):'';
  OUT.push('<div class="rv-it"><a href="'+lm[1]+'">'+t+'</a>'+(im&&im[1]?'<img src="'+im[1]+'">':'')+(dt?'<span class="rv-date">'+dt+'</span>':'')+'</div>');
}
result=OUT;

