function removeByClasses(html, classes) {
  var re = /<(\/?)([a-zA-Z0-9]+)([^>]*?)(\/?)>/g;
  var result = '';
  var last = 0;
  var removing = null;
  var m;
  while ((m = re.exec(html)) !== null) {
    var close = m[1] === '/';
    var tag = m[2].toLowerCase();
    var attrs = m[3];
    var selfClose = m[4] === '/';
    if (removing === null) {
      if (!close) {
        var cm = attrs.match(/class\s*=\s*["']([^"']*)["']/i);
        var cl = cm ? cm[1] : '';
        var hit = classes.some(function(c){return (' ' + cl + ' ').indexOf(' ' + c + ' ') !== -1;});
        if (hit) { removing = {tag: tag, depth: 1}; last = re.lastIndex; continue; }
      }
      result += html.slice(last, re.lastIndex);
      last = re.lastIndex;
    } else {
      if (!close && tag === removing.tag && !selfClose) removing.depth++;
      else if (close && tag === removing.tag) {
        removing.depth--;
        if (removing.depth === 0) { removing = null; last = re.lastIndex; continue; }
      }
      last = re.lastIndex;
    }
  }
  result += html.slice(last);
  return result;
}

function extractM3u8FromConfig(substr) {
  var dm = substr.match(/data-config=(["'])([\s\S]*?)\1/);
  if (!dm) return '';
  var raw = dm[2].replace(/&quot;/g,'"').replace(/&amp;/g,'&').replace(/&#39;/g,"'");
  try {
    var cfg = JSON.parse(raw);
    var u = cfg.video && cfg.video.url;
    return (typeof u === 'string') ? u : '';
  } catch(e) { return ''; }
}

var AD_CLASSES = ["txt-apps","article-ads-btn","article-download","content-copyright","post-near","hot-news-section","hot-news-box","hot-news-content","content-tabs","app-download","download-section","links-box","link-list","links-list","app-copy-btn","copy-box","navigation-link","btn-download","a2a_kit","a2a_kit_size_32","a2a_default_style","tags","keywords","row-link","tip","important-tip","tip-content","article-ads","related-posts","post-ads","tips-box","flash","text-line-ellipsis-2","ads-img","qrcode-img","app-img"];
var h = String(result);
var pm = h.match(/class="post-content" itemprop="articleBody">([\s\S]*?)<\/article>/);
var pc = pm ? pm[1] : h;

// 1) 尾部截断：无用内容区
var CUT = ["内娱女星 景甜 黑料合集","相关文章","关键词：","点击观看","相关推荐","猜你喜欢","常见问题解答"];
// 先扫视频容器结束位置：CUT 截断点不得落在视频区之前/之内
var lastVidEnd = -1;
var vdRe = /<div[^>]*class="dplayer"/g;
var vdM2, vdS2, vdD2, vdP2, vdOp2, vdCl2;
while ((vdM2 = vdRe.exec(pc)) !== null) {
  vdS2 = vdM2.index; vdD2 = 0; vdP2 = vdS2;
  while (vdP2 < pc.length) {
    vdOp2 = pc.indexOf('<div', vdP2);
    vdCl2 = pc.indexOf('</div>', vdP2);
    if (vdCl2 === -1) break;
    if (vdOp2 !== -1 && vdOp2 < vdCl2) { vdD2++; vdP2 = vdOp2 + 4; }
    else { vdD2--; vdP2 = vdCl2 + 6; if (vdD2 === 0) break; }
  }
  if (vdP2 > lastVidEnd) lastVidEnd = vdP2;
}
var cutPos = -1;
for (var ci=0; ci<CUT.length; ci++){
  var p = pc.indexOf(CUT[ci]);
  if (p!==-1 && p > lastVidEnd && (cutPos===-1 || p<cutPos)) cutPos = p;
}
if (cutPos!==-1) {
  var cand = [];
  var o1 = pc.lastIndexOf('<blockquote', cutPos); if(o1!==-1) cand.push(o1);
  var o2 = pc.lastIndexOf('<p', cutPos); if(o2!==-1) cand.push(o2);
  var o3 = pc.lastIndexOf('<div', cutPos); if(o3!==-1) cand.push(o3);
  var o4 = pc.lastIndexOf('<h', cutPos); if(o4!==-1) cand.push(o4);
  if(cand.length){
    cand.sort(function(a,b){return b-a;});
    var best = cand[0];
    if (best >= cutPos - 1200 && best >= lastVidEnd) cutPos = best;
  }
